package com.company.project.wishlist.repository;

import java.time.Instant;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;

/**
 * Each user's saved hotels, implemented in {@code impl/WishlistRepositoryImpl}. Nothing here can be generated by
 * Spring Data, so this is a plain interface.
 */
public interface WishlistRepository {

	/**
	 * Saves the hotel for the user unless it is already saved, in one statement, so saving twice (or twice at once)
	 * never conflicts. A repeat keeps the first {@code savedAt}.
	 *
	 * @return the number of entries added: 1, or 0 when the hotel was already saved
	 */
	int addIfAbsent(long userId, long hotelId, Instant savedAt);

	/** @return the number of entries removed: 1, or 0 when the hotel wasn't saved */
	int remove(long userId, long hotelId);

	/**
	 * The user's entries, newest first (ties: the higher hotel id first), each with whether its hotel is still
	 * listed. Ignores any sort in the Pageable.
	 */
	Page<WishlistEntryView> findPage(long userId, Pageable pageable);

}
